/** Ordinary native Views client; Account crypto and storage live in :credentials. */
public class MessengerActivity extends Activity {
 private CredentialConnection connection;private boolean working=false,ready=false,signedIn=false,chatLocked=false,wide=false;
 private JSONObject status=new JSONObject();private JSONArray accounts=new JSONArray(),contacts=new JSONArray();private String peer,lastPeer,lastText,operationId;
 private TextView accountLabel,nodeStatus,notice,chatTitle;private Button accountButton,logoutButton,importButton,createButton,nodeButton,connectionsButton,refreshButton,sendButton,cancelButton;
 private LinearLayout root,chatPane,history;private ListView chatList;private ScrollView historyScroll;private EditText compose;private ProgressBar progress;
 private final Handler main=new Handler(Looper.getMainLooper());private static final int IMPORT=41;
 private JSONObject obj(Object... values){JSONObject value=new JSONObject();try{for(int i=0;i<values.length;i+=2)value.put((String)values[i],values[i+1]);}catch(JSONException e){throw new IllegalArgumentException(e);}return value;}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private TextView label(String text,int size,int color){TextView view=new TextView(this);view.setText(text);view.setTextSize(size);view.setTextColor(color);return view;}
 private Button button(String text){Button view=new Button(this);view.setText(text);view.setAllCaps(false);return view;}
 private LinearLayout row(){LinearLayout view=new LinearLayout(this);view.setOrientation(LinearLayout.HORIZONTAL);view.setGravity(Gravity.CENTER_VERTICAL);return view;}
 @Override public void onCreate(Bundle state){
  super.onCreate(state);wide=getResources().getConfiguration().screenWidthDp>=700;buildViews();
  try{startForegroundService(new Intent(this,CredentialService.class));}catch(Exception e){notice.setText("The message service could not start. Open D-MASH again to retry.");return;}
  connection=new CredentialConnection(this,new CredentialConnection.Listener(){public void ready(JSONObject value){ready=true;status=value;updateStatus();loadAccounts();}public void busy(boolean value){working=value;updateControls();}public void disconnected(String code){ready=false;signedIn=false;peer=null;history.removeAllViews();nodeStatus.setText("Message service unavailable");notice.setText("Reopen D-MASH to reconnect. Your stored messages were kept.");updateControls();}});
 }
 private void buildViews(){
  root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(245,249,249));root.setPadding(dp(16),dp(12),dp(16),dp(10));
  LinearLayout heading=row();TextView brand=label("D-MASH",25,Color.rgb(20,110,115));brand.setTypeface(null,1);heading.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button about=button("Details");about.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("D-MASH").setMessage("Native messenger development version. Your profile and encrypted history stay on this device. Node runs in a separate background process. Android may stop background work; reopening D-MASH reconnects the interface.").setNeutralButton("Node tools",(d,w)->startActivity(new Intent(this,NodeDiagnosticsActivity.class))).setNegativeButton("Close",null).show());heading.addView(about);root.addView(heading);
  accountLabel=label("Connecting to your messages…",14,Color.rgb(76,101,108));root.addView(accountLabel);
  LinearLayout accountActions=row();accountButton=button("Sign in");accountButton.setOnClickListener(v->{if(status.optBoolean("rootLocked"))unlock(false,null,this::showLogin);else showLogin();});logoutButton=button("Sign out");logoutButton.setOnClickListener(v->call("account.logout",obj(),result->{clearAccount();refreshStatus();notice.setText("Signed out. Node keeps its own lifetime.");}));importButton=button("Import profile");importButton.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,IMPORT);});accountActions.addView(accountButton);accountActions.addView(logoutButton);root.addView(accountActions);LinearLayout profiles=row();profiles.addView(importButton);createButton=button("Create profile");createButton.setOnClickListener(v->{if(!status.optBoolean("profileExists"))createProfile();else if(status.optBoolean("rootLocked"))unlock(false,null,this::createAccount);else createAccount();});profiles.addView(createButton);root.addView(profiles);
  nodeStatus=label("Checking Node…",13,Color.rgb(83,111,118));root.addView(nodeStatus);LinearLayout network=row();nodeButton=button("Start Node");nodeButton.setOnClickListener(v->{if(status.optBoolean("nodeRunning"))call("node.disable",obj(),result->{clearAccount();refreshStatus();notice.setText("Node stopped. Device locked.");});else startNode();});refreshButton=button("Refresh");refreshButton.setOnClickListener(v->refreshStatus());network.addView(nodeButton);connectionsButton=button("Connections");connectionsButton.setOnClickListener(v->connections());network.addView(connectionsButton);network.addView(refreshButton);root.addView(network);
  notice=label("",14,Color.rgb(130,75,64));notice.setPadding(0,dp(4),0,dp(4));root.addView(notice);LinearLayout activity=row();progress=new ProgressBar(this);activity.addView(progress,new LinearLayout.LayoutParams(dp(24),dp(24)));cancelButton=button("Cancel");cancelButton.setOnClickListener(v->{if(connection!=null)connection.cancel();});activity.addView(cancelButton);root.addView(activity);
  LinearLayout content=new LinearLayout(this);content.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));chatList=new ListView(this);chatList.setContentDescription("Conversations");chatList.setBackgroundColor(Color.WHITE);chatList.setOnItemClickListener((parent,view,position,id)->openChat(contacts.optJSONObject(position)));content.addView(chatList,wide?new LinearLayout.LayoutParams(dp(260),-1):new LinearLayout.LayoutParams(-1,-1));
  chatPane=new LinearLayout(this);chatPane.setOrientation(LinearLayout.VERTICAL);if(wide)chatPane.setPadding(dp(12),0,0,0);content.addView(chatPane,wide?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,-1));LinearLayout title=row();Button back=button("Back");back.setVisibility(wide?View.GONE:View.VISIBLE);back.setOnClickListener(v->backToChats());title.addView(back);chatTitle=label("Choose a conversation",20,Color.rgb(28,62,69));title.addView(chatTitle,new LinearLayout.LayoutParams(0,-2,1));chatPane.addView(title);
  historyScroll=new ScrollView(this);historyScroll.setFillViewport(true);historyScroll.setBackgroundColor(Color.rgb(235,245,242));history=new LinearLayout(this);history.setOrientation(LinearLayout.VERTICAL);history.setPadding(dp(8),dp(8),dp(8),dp(8));historyScroll.addView(history);chatPane.addView(historyScroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout composer=row();compose=new EditText(this);compose.setHint("Message");compose.setContentDescription("Message");compose.setMaxLines(4);compose.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);compose.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16384)});composer.addView(compose,new LinearLayout.LayoutParams(0,-2,1));sendButton=button("Send");sendButton.setOnClickListener(v->send());composer.addView(sendButton);chatPane.addView(composer);compose.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){updateControls();}public void afterTextChanged(Editable e){}});
  if(!wide)chatPane.setVisibility(View.GONE);setContentView(root);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());android.graphics.Insets ime=insets.getInsets(WindowInsets.Type.ime());view.setPadding(dp(16)+bars.left,dp(10)+bars.top,dp(16)+bars.right,dp(8)+Math.max(bars.bottom,ime.bottom));return insets;});}updateControls();
 }
 private void call(String method,JSONObject params,java.util.function.Consumer<JSONObject> success){if(connection==null||working||!ready)return;notice.setText("");connection.request(method,params,(ok,code,result)->{if(isFinishing())return;if(ok)success.accept(result);else{notice.setText(code.equals("ACCOUNT_SESSION_CHANGED")?"Action cancelled.":code.contains("PASSWORD")||code.contains("LOGIN")?"Could not sign in. Check your Account password.":code.equals("ROOT_UNLOCK_REQUIRED")?"Unlock your device to continue.":"Could not complete this action. Your stored messages were kept.");if(code.equals("ROOT_UNLOCK_REQUIRED")){try{status.put("rootLocked",true);}catch(JSONException ignored){}updateControls();}}});}
 private void loadAccounts(){call("account.listAccounts",obj(),result->{accounts=result.optJSONArray("rows");if(accounts==null)accounts=new JSONArray();JSONObject value=result.optJSONObject("value");JSONObject active=value==null?null:value.optJSONObject("activeAccount");if(active!=null&&active.length()>0){signedIn=true;accountLabel.setText(active.optString("displayName","Account"));loadContacts();}else{accountLabel.setText(accounts.length()==0?"Import your profile to open your conversations":"Sign in to open your conversations");updateControls();}});}
 private void refreshStatus(){call("host.status",obj(),result->{JSONObject value=result.optJSONObject("value");if(value!=null)status=value;updateStatus();});}
 private void updateStatus(){JSONObject node=status.optJSONObject("node");boolean running=status.optBoolean("nodeRunning");nodeStatus.setText(running?(node==null||!node.has("connectedPeers")||"unavailable".equals(status.optString("nodeState"))?"Node process running · checking connections…":"Node running · "+node.optInt("connectedPeers")+" connected peers"):"Node is off");updateControls();}
 private void updateControls(){if(accountButton==null)return;accountButton.setVisibility(signedIn?View.GONE:View.VISIBLE);logoutButton.setVisibility(signedIn?View.VISIBLE:View.GONE);accountButton.setText(status.optBoolean("profileExists")&&status.optBoolean("rootLocked")?"Unlock device":"Sign in");accountButton.setEnabled(ready&&!working&&(accounts.length()>0||status.optBoolean("profileExists")));logoutButton.setEnabled(!working);importButton.setVisibility(signedIn?View.GONE:View.VISIBLE);importButton.setEnabled(ready&&!working&&!signedIn);createButton.setVisibility(signedIn?View.GONE:View.VISIBLE);createButton.setText(status.optBoolean("profileExists")?"Create Account":"Create profile");createButton.setEnabled(ready&&!working);nodeButton.setText(status.optBoolean("nodeRunning")?"Stop Node and lock":"Start Node");nodeButton.setEnabled(ready&&!working&&status.optBoolean("profileExists"));connectionsButton.setEnabled(ready&&!working&&status.optBoolean("profileExists")&&!status.optBoolean("nodeRunning"));refreshButton.setEnabled(ready&&!working);progress.setVisibility(working?View.VISIBLE:View.GONE);cancelButton.setVisibility(working?View.VISIBLE:View.GONE);compose.setEnabled(signedIn&&peer!=null&&!chatLocked&&!working);sendButton.setEnabled(compose.isEnabled()&&!compose.getText().toString().trim().isEmpty());chatList.setEnabled(signedIn&&!working);}
 private void unlock(boolean importing,JSONObject profile,Runnable after){EditText pin=new EditText(this);pin.setHint("Device PIN");pin.setInputType(129);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Unlock device").setView(pin).setPositiveButton("Unlock",null).setNegativeButton("Cancel",(d,w)->pin.setText("")).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{String value=pin.getText().toString();pin.setText("");dialog.dismiss();call(importing?"profile.import":"root.unlock",importing?obj("profile",profile,"pin",value):obj("pin",value),result->{accounts=result.optJSONArray("rows");if(accounts==null)accounts=new JSONArray();try{status.put("rootLocked",false);status.put("profileExists",true);}catch(JSONException ignored){}updateControls();if(after!=null)after.run();});}));dialog.show();}
 private LinearLayout form(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),0);return form;}
 private EditText field(LinearLayout form,String hint,boolean secret){EditText input=new EditText(this);input.setHint(hint);input.setSingleLine(true);if(secret)input.setInputType(129);form.addView(input);return input;}
 private void createProfile(){LinearLayout form=form();EditText pin=field(form,"Device PIN",true),confirm=field(form,"Confirm PIN",true);TextView error=label("",14,Color.rgb(130,75,64));form.addView(error);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Create your profile").setView(form).setPositiveButton("Create profile",null).setNegativeButton("Cancel",(d,w)->{pin.setText("");confirm.setText("");}).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{String value=pin.getText().toString();if(value.isEmpty()||!value.equals(confirm.getText().toString())){error.setText("Enter the same PIN in both fields.");return;}pin.setText("");confirm.setText("");dialog.dismiss();call("profile.create",obj("pin",value),result->{try{status.put("profileExists",true);status.put("rootLocked",false);}catch(JSONException ignored){}updateControls();createAccount();});}));dialog.show();}
 private void createAccount(){LinearLayout form=form();EditText identity=field(form,"Account name",false),display=field(form,"Display name (optional)",false),password=field(form,"Account password",true),confirm=field(form,"Confirm password",true);TextView error=label("",14,Color.rgb(130,75,64));form.addView(error);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Create Account").setView(form).setPositiveButton("Create and sign in",null).setNegativeButton("Cancel",(d,w)->{password.setText("");confirm.setText("");}).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{String name=identity.getText().toString().trim(),secret=password.getText().toString(),label=display.getText().toString().trim();if(name.isEmpty()||secret.isEmpty()||!secret.equals(confirm.getText().toString())){error.setText("Enter an Account name and the same password in both fields.");return;}password.setText("");confirm.setText("");dialog.dismiss();call("account.create",obj("identity",name,"password",secret,"displayName",label),result->{JSONObject created=result.optJSONObject("value");accounts.put(created==null?obj("identity",name):created);call("account.login",obj("identity",name,"password",secret),loggedIn->{signedIn=true;JSONObject account=loggedIn.optJSONObject("value");accountLabel.setText(account==null?name:account.optString("displayName",name));loadContacts();});});}));dialog.show();}
 private void showLogin(){if(accounts.length()==0){notice.setText("Import an existing profile first.");return;}LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),0);Spinner choice=new Spinner(this);ArrayList<String> names=new ArrayList<>();for(int i=0;i<accounts.length();i++){JSONObject a=accounts.optJSONObject(i);names.add(a.optString("name",a.optString("displayName",a.optString("identity"))));}choice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));form.addView(choice);EditText password=new EditText(this);password.setHint("Account password");password.setInputType(129);form.addView(password);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Sign in").setView(form).setPositiveButton("Sign in",null).setNegativeButton("Cancel",(d,w)->password.setText("")).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{JSONObject selected=accounts.optJSONObject(choice.getSelectedItemPosition());String identity=selected.optString("identity",selected.optString("id"));String secret=password.getText().toString();password.setText("");dialog.dismiss();call("account.login",obj("identity",identity,"password",secret),result->{signedIn=true;JSONObject value=result.optJSONObject("value");accountLabel.setText(value==null?"Account":value.optString("displayName","Account"));loadContacts();});}));dialog.show();}
 private void loadContacts(){call("account.contacts",obj(),result->{contacts=result.optJSONArray("rows");if(contacts==null)contacts=new JSONArray();ArrayList<String> names=new ArrayList<>();for(int i=0;i<contacts.length();i++)names.add(contacts.optJSONObject(i).optString("name"));chatList.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,names));notice.setText(contacts.length()==0?"No conversations yet.":"");updateControls();});}
 private void openChat(JSONObject contact){if(contact==null)return;peer=contact.optString("id");chatLocked=contact.optBoolean("chatLocked");chatTitle.setText(contact.optString("name"));history.removeAllViews();if(!wide){chatList.setVisibility(View.GONE);chatPane.setVisibility(View.VISIBLE);}loadHistory();}
 private void loadHistory(){if(peer==null)return;call("account.history",obj("peer",peer,"before",0,"limit",50),result->{history.removeAllViews();JSONArray rows=result.optJSONArray("rows");ArrayList<JSONObject> sorted=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++)sorted.add(rows.optJSONObject(i));sorted.sort(Comparator.comparingLong(value->value.optLong("sequence")));for(JSONObject value:sorted){LinearLayout line=new LinearLayout(this);line.setGravity(value.optString("direction").equals("out")?Gravity.RIGHT:Gravity.LEFT);LinearLayout bubble=new LinearLayout(this);bubble.setOrientation(LinearLayout.VERTICAL);bubble.setPadding(dp(12),dp(8),dp(12),dp(8));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(value.optString("direction").equals("out")?Color.rgb(211,237,230):Color.WHITE);shape.setCornerRadius(dp(12));bubble.setBackground(shape);TextView text=label(value.optString("text"),16,Color.rgb(25,53,60));text.setMaxWidth(dp(wide?500:280));bubble.addView(text);long time=value.optLong("time");String meta=time>0?DateFormat.getTimeInstance(DateFormat.SHORT).format(new Date(time)):"";if(value.optString("state").equals("LOCAL"))meta+=" · Saved";else if(value.optString("state").equals("NODE_ACCEPTED"))meta+=" · Queued";TextView stamp=label(meta,11,Color.rgb(88,120,122));stamp.setGravity(Gravity.RIGHT);bubble.addView(stamp);LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-2,-2);margin.setMargins(0,dp(4),0,dp(4));line.addView(bubble,margin);history.addView(line);}notice.setText(chatLocked?"This conversation is locked.":"");updateControls();historyScroll.post(()->historyScroll.fullScroll(View.FOCUS_DOWN));});}
 private void send(){if(peer==null||working)return;String text=compose.getText().toString();if(operationId==null||!peer.equals(lastPeer)||!text.equals(lastText))operationId=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");lastPeer=peer;lastText=text;call("account.sendText",obj("peer",peer,"operationId",operationId,"text",text),result->{JSONObject value=result.optJSONObject("value");if(value!=null&&value.optBoolean("accepted")){operationId=null;compose.setText("");loadHistory();}else notice.setText("The message has not been accepted. Please try again.");});}
 private void startNode(){JSONObject policy=status.optJSONObject("nodePolicy");JSONArray endpoints=policy==null?null:policy.optJSONArray("endpoints");startNode(endpoints==null?new JSONArray():endpoints,policy!=null&&policy.optBoolean("directEnabled"));}
 private void startNode(JSONArray endpoints,boolean direct){Runnable start=()->call("node.enable",obj("endpoints",endpoints,"directEnabled",direct),result->refreshStatus());if(status.optBoolean("rootLocked"))unlock(false,null,start);else start.run();}
 private void connections(){
  LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),0);TextView help=label("Enter the connection details supplied by your network. Empty connections keep Node available locally until a peer is configured.",14,Color.rgb(76,101,108));form.addView(help);LinearLayout entries=new LinearLayout(this);entries.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(this);scroll.addView(entries);form.addView(scroll,new LinearLayout.LayoutParams(-1,dp(210)));ArrayList<EditText[]> fields=new ArrayList<>();
  java.util.function.Consumer<JSONObject> add=value->{LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);EditText address=new EditText(this);address.setHint("Server address (wss://…)");address.setSingleLine(true);address.setInputType(17);address.setText(value.optString("url"));row.addView(address);LinearLayout keyRow=row();EditText key=new EditText(this);key.setHint("Node key");key.setSingleLine(true);key.setText(value.optString("nodeId"));keyRow.addView(key,new LinearLayout.LayoutParams(0,-2,1));Button remove=button("Remove");keyRow.addView(remove);row.addView(keyRow);EditText[] pair={address,key};fields.add(pair);remove.setOnClickListener(v->{fields.remove(pair);entries.removeView(row);});entries.addView(row);};
  JSONObject policy=status.optJSONObject("nodePolicy");JSONArray existing=policy==null?null:policy.optJSONArray("endpoints");if(existing!=null)for(int i=0;i<existing.length();i++)add.accept(existing.optJSONObject(i));Button addButton=button("Add connection");addButton.setOnClickListener(v->{if(fields.size()<8)add.accept(obj());});form.addView(addButton);CheckBox direct=new CheckBox(this);direct.setText("Allow direct connections");direct.setChecked(policy!=null&&policy.optBoolean("directEnabled"));form.addView(direct);TextView error=label("",14,Color.rgb(130,75,64));form.addView(error);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Node connections").setView(form).setPositiveButton("Start Node",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{JSONArray endpoints=new JSONArray();for(EditText[] pair:fields){String address=pair[0].getText().toString().trim(),key=pair[1].getText().toString().trim();android.net.Uri uri=android.net.Uri.parse(address);if(!("ws".equals(uri.getScheme())||"wss".equals(uri.getScheme()))||uri.getHost()==null||!key.matches("[0-9a-f]{64}")){error.setText("Enter a ws:// or wss:// server address and its 64-character Node key.");return;}endpoints.put(obj("url",address,"nodeId",key));}dialog.dismiss();startNode(endpoints,direct.isChecked());}));dialog.show();
 }
 private void clearAccount(){signedIn=false;peer=null;compose.setText("");history.removeAllViews();contacts=new JSONArray();chatList.setAdapter(null);accountLabel.setText("Signed out");backToChats();updateControls();}
 private void backToChats(){if(wide)return;peer=null;chatPane.setVisibility(View.GONE);chatList.setVisibility(View.VISIBLE);updateControls();}
 @Override public void onBackPressed(){if(!wide&&chatPane.getVisibility()==View.VISIBLE)backToChats();else super.onBackPressed();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=IMPORT||result!=RESULT_OK||data==null||data.getData()==null)return;try(InputStream input=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(output.size()+count>128*1024*1024)throw new IOException("size");output.write(buffer,0,count);}JSONObject profile=new JSONObject(new String(output.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));unlock(true,profile,()->{notice.setText("Profile imported. Sign in to open your conversations.");refreshStatus();});}catch(Exception e){notice.setText("Choose a complete D-MASH profile export. The source was kept.");}}
 @Override public void onDestroy(){if(connection!=null)connection.close();super.onDestroy();}
}
